pub mod client;

/// Identifies a request sent by Tauri; core echoes it on the matching response.
pub type RequestId = u64;

/// Identifies one call (generated by the frontend, opaque to core and Tauri).
/// `CallStart`, `CallStartResult`, `CallEnd`, `CallEnded` and `RoomConnectionFailed` carry it
/// so a message about an old call can never tear down a newer one.
pub type CallId = u64;

/// Frames larger than this are treated as a corrupt stream.
pub const MAX_FRAME_BYTES: u64 = 64 * 1024 * 1024;

// Platform-specific imports
#[cfg(unix)]
use std::os::unix::net::{UnixListener, UnixStream};

#[cfg(windows)]
use std::net::{TcpListener, TcpStream};

