impl ScreenShareResolution {
    pub fn extent(self) -> Extent {
        match self {
            ScreenShareResolution::P1080 => Extent {
                width: 1920.0,
                height: 1080.0,
            },
            ScreenShareResolution::P1440 => Extent {
                width: 2560.0,
                height: 1440.0,
            },
            ScreenShareResolution::P4K => Extent {
                width: 4096.0,
                height: 2160.0,
            },
        }
    }
}

